// Free, legally usable audio (Creative Commons / public domain, from the
// Internet Archive) used by the audiobook player, since we don't have the
// real audiobook audio. Generated by scripts/fetch-podcasts.mjs.
// Server-safe: no browser APIs.

import data from "@/data/audio-samples.json"

export type AudioSample = {
  id: string
  title: string
  /** BCP 47-ish language code, e.g. "fa". */
  language: string
  audioUrl: string
  durationSeconds: number | null
  /** Human-readable license name, e.g. "CC BY-NC-ND 4.0". */
  license: string
  licenseUrl: string
  attribution: string
  sourceUrl: string
}

type AudioSamplesFile = {
  generatedAt: string
  samples: AudioSample[]
}

const samples = (data as AudioSamplesFile).samples

export function getAudioSamples(): AudioSample[] {
  return samples
}

/** Deterministic sample for a book: the same book always gets the same audio. */
export function getSampleForBook(bookId: number): AudioSample {
  const index = Math.abs(Math.trunc(bookId)) % samples.length
  return samples[index]
}
